// 视觉理解 Chat API
import { API_CONFIG } from './config';

/**
 * 将本地/临时路径图片读取为 base64 dataURL（uni-app 端）
 * @param {string} filePath
 * @param {string} mimeType 例如 image/jpeg、image/png
 * @returns {Promise<string>} dataURL
 */
export function readImageAsDataUrl(filePath, mimeType = 'image/jpeg') {
  return new Promise((resolve, reject) => {
    if (typeof uni !== 'undefined' && uni.getFileSystemManager) {
      uni.getFileSystemManager().readFile({
        filePath,
        encoding: 'base64',
        success: (res) => {
          resolve(`data:${mimeType};base64,${res.data}`);
        },
        fail: (err) => reject(new Error(`读取图片失败: ${err.errMsg}`))
      });
    } else if (typeof window !== 'undefined' && window.FileReader) {
      // H5 回退：通过 <img> + canvas 读为 dataURL
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = function() {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0);
        resolve(canvas.toDataURL(mimeType));
      };
      img.onerror = function() { reject(new Error('图片加载失败')); };
      img.src = filePath;
    } else {
      reject(new Error('不支持的运行环境'));
    }
  });
}

/**
 * 视觉理解对话：可同时传入图片和文本
 * @param {Array<{type:'image'|'text', value:string, mimeType?:string}>} inputs
 *   - image: value 为本地/临时路径或可访问 URL
 *   - text: value 为文本
 * @param {object} opts
 * @param {string} opts.model 指定模型，默认配置中的视觉模型
 * @param {number} opts.maxTokens 最大生成 token
 * @returns {Promise<string>} 返回模型文本回复
 */
export async function visionChat(inputs, opts = {}) {
  // 统一使用已开通的思考版视觉模型（同时兼容纯文本与图文）
  const containsImage = Array.isArray(inputs) && inputs.some(i => i.type === 'image');
  const model = opts.model || API_CONFIG.DEFAULT_CHAT_MODEL;
  const maxTokens = typeof opts.maxTokens === 'number' ? opts.maxTokens : 300;

  // 组装 messages content
  let content = [];
  for (const item of inputs) {
    if (item.type === 'image') {
      const isUrl = /^https?:\/\//i.test(item.value) || item.value.startsWith('data:');
      let imageUrl = item.value;
      if (!isUrl) {
        const mime = item.mimeType || 'image/jpeg';
        imageUrl = await readImageAsDataUrl(item.value, mime);
      }
      content.push({
        type: 'image_url',
        image_url: { url: imageUrl }
      });
    } else if (item.type === 'text') {
      content.push({ type: 'text', text: item.value });
    }
  }

  // 如果全是纯文本，按字符串作为 content 传入（与 API 示例一致）
  const isPureText = content.length > 0 && content.every(p => p.type === 'text');
  if (isPureText && !containsImage) {
    content = content.map(p => p.text).join('\n');
  }

  const payload = {
    model,
    messages: [
      {
        role: 'user',
        content
      }
    ],
    max_tokens: maxTokens
  };

  try {
    // 调试：打印精简后的请求信息（不打印密钥，不打印大体量二进制）
    const debugPreview = {
      url: `${API_CONFIG.BASE_URL}${API_CONFIG.CHAT_COMPLETIONS_ENDPOINT}`,
      model,
      containsImage,
      isPureText: typeof content === 'string',
      maxTokens,
      // 消息内容只展示类型与长度
      messagesPreview:
        typeof content === 'string'
          ? `${content.slice(0, 120)}${content.length > 120 ? '…' : ''}`
          : content.map((c, i) =>
              c.type === 'text'
                ? { idx: i, type: c.type, len: (c.text || '').length }
                : { idx: i, type: c.type, hasUrl: !!(c.image_url && c.image_url.url), urlPrefix: (c.image_url && c.image_url.url || '').slice(0, 16) }
            ),
    };
    console.log('[visionChat] request preview:', debugPreview);

    const res = await uni.request({
      url: `${API_CONFIG.BASE_URL}${API_CONFIG.CHAT_COMPLETIONS_ENDPOINT}`,
      method: 'POST',
      header: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${API_CONFIG.API_KEY}`
      },
      data: payload
    });

    const requestId = res.header?.['x-request-id'] || res.header?.['X-Request-Id'] || res.data?.id;
    console.log('[visionChat] response status:', res.statusCode, 'requestId:', requestId);
    if (res.statusCode !== 200) {
      console.log('[visionChat] response data (error):', res.data);
    } else {
      console.log('[visionChat] response data (ok):', res.data);
    }

    if (res.statusCode === 200) {
      const choice = res.data?.choices?.[0];
      const msgContent = choice?.message?.content;
      if (typeof msgContent === 'string') return msgContent;
      if (Array.isArray(msgContent)) {
        const textPart = msgContent.find(p => p.type === 'text');
        return textPart?.text || '';
      }
      return '';
    } else {
      const errMsg = res.data?.error?.message || JSON.stringify(res.data);
      throw new Error(`Chat API 失败: ${res.statusCode} ${errMsg}`);
    }
  } catch (err) {
    console.error('visionChat error:', err);
    throw err;
  }
}


